class TheaterReservation:
    def __init__(self):
        self.reservations = []

    def reserve_tickets(self, play_name, num_tickets):
        for play in self.reservations:
            if play['name'] == play_name:
                play['tickets'] += num_tickets
                break
        else:
            self.reservations.append({'name': play_name, 'tickets': num_tickets})

    def cancel_reservation(self, play_name, num_tickets):
        for play in self.reservations:
            if play['name'] == play_name:
                if num_tickets <= play['tickets']:
                    play['tickets'] -= num_tickets
                else:
                    print("Cannot cancel more tickets than reserved.")
                break
        else:
            print("Play not found.")

    def check_availability(self, play_name):
        for play in self.reservations:
            if play['name'] == play_name:
                return play['tickets']
        return 0
```

