public class MaxValueFinder {
    public static int findMaxValue(int[] arr) {
        if (arr == null || arr.length == 0) {
            throw new IllegalArgumentException("Input array is empty or null");
        }

        int max = arr[0];
        for (int i = 1; i < arr.length; i++) {
