```typescript
type Wrappable<T> = Iterable<T> | ArrayLike<T>;

function take<T>(n: number, iterable: Wrappable<T>): IterableIterator<T>;
function take<T>(n: number): (iterable: Wrappable<T>) => IterableIterator<T>;
function take<T>(n: number, iterable?: Wrappable<T>): any {
  function* takeGenerator(iterable: Wrappable<T>): IterableIterator<T> {
    for (let i = 0; i < n; i++) {
      yield iterable[i];
    }
  }

  if (iterable) {
    return takeGenerator(iterable);
  } else {
    return (iterable: Wrappable<T>) => takeGenerator(iterable);
  }
}

// Example usage
const arr = [1, 2, 3, 4, 5];
const take3 = take(3, arr);
console.log([...take3]); // Output: [1, 2, 3]

const take2Curried = take(2);
const take2FromArr = take2Curried(arr);
console.log([...take2FromArr]); // Output: [1, 2]
```

