```python
class Form:
    def __init__(self):
        self.fields = []

    def add_text_field(self, name):
        self.fields.append({"name": name, "type": "text"})

    def add_number_field(self, name):
        self.fields.append({"name": name, "type": "number"})

    def add_date_field(self, name):
        self.fields.append({"name": name, "type": "date"})

    def validate_field(self, name, value):
