class Hsv {
  constructor({ h, s, v }) {
    this.h = h;
    this.s = s;
    this.v = v;
  }
}

function rgbToHsv(rgbColor) {
  const r = rgbColor.r / 255;
  const g = rgbColor.g / 255;
  const b = rgbColor.b / 255;

  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const delta = max - min;

  let h = 0;
  if (delta !== 0) {
    if (max === r) {
      h = (g - b) / delta + (g < b ? 6 : 0);
    } else if (max === g) {
      h = (b - r) / delta + 2;
    } else {
      h = (r - g) / delta + 4;
    }
    h *= 60;
  }

  const s = max === 0 ? 0 : delta / max;
  const v = max;

  h = Math.round(h);
  h += h < 0 ? 360 : 0;

  return new Hsv({ h, s, v });
}
