```typescript
function parseCodeSnippet(code: string): { namespaces: string[], types: string[] } {
  const namespaces: string[] = [];
  const types: string[] = [];

  const regexNamespace = /@namespace\s+([\w.]+)/g;
  const regexType = /@docid\s*\n\s*@type\s+([\w]+)/g;

  let match;
  while ((match = regexNamespace.exec(code)) !== null) {
    namespaces.push(match[1]);
  }

  while ((match = regexType.exec(code)) !== null) {
    types.push(match[1]);
  }

  return { namespaces, types };
}

