def pack_canvas(canvas, objects):
    def is_valid_position(x, y, width, height):
        for i in range(x, x + width):
            for j in range(y, y + height):
                if i < 0 or i >= len(canvas) or j < 0 or j >= len(canvas[0]) or canvas[i][j] == 1:
                    return False
        return True

